use loro::{LoroDoc,ExportMode};use serde_json::json;
fn random(seed:&mut u32,n:usize)->usize{*seed^=*seed<<13;*seed^=*seed>>17;*seed^=*seed<<5;*seed as usize%n}
fn main(){let mut seed=65981;for trial in 0..160{let n=3+random(&mut seed,3);let peers:Vec<LoroDoc>=(0..n).map(|i|{let d=LoroDoc::new();d.set_peer_id(i as u64+1).unwrap();d}).collect();let mut steps=vec![];for _ in 0..70{let peer=random(&mut seed,n);if random(&mut seed,4)==0{let from=random(&mut seed,n);let update=peers[from].export(ExportMode::all_updates()).unwrap();peers[peer].import(&update).unwrap();steps.push(json!({"peer":peer,"from":from,"text":peers[peer].get_text("text").to_string()}));}else{let text=peers[peer].get_text("text");let n=text.len_unicode();let insert=n==0||random(&mut seed,4)!=0;let position=random(&mut seed,n+usize::from(insert));let value=[97+random(&mut seed,26)as u32,233,30000,128578][random(&mut seed,4)];if insert{text.insert(position,&char::from_u32(value).unwrap().to_string()).unwrap();}else{text.delete(position,1).unwrap();}peers[peer].commit();steps.push(json!({"peer":peer,"insert":insert,"position":position,"value":value,"text":text.to_string()}));}}for peer in 0..n{for from in 0..n{let update=peers[from].export(ExportMode::all_updates()).unwrap();peers[peer].import(&update).unwrap();steps.push(json!({"peer":peer,"from":from,"text":peers[peer].get_text("text").to_string()}));}}println!("{}",json!({"trial":trial,"peers":n,"steps":steps}));}}
